// ---- Settings you can edit -----------------------------------------------------------------------------
const settings = {
  sheetId: '',                  // the Google Sheet id: the long part of its URL between /d/ and /edit
  sheetName: 'Flow batch',      // the tab with the columns listed in the main note's Setup
  maxRowsPerRun: 10,            // rows taken per run. Each video takes about 1 to 3 minutes
  defaultType: 'image+video',   // used when a row leaves type empty: image, video or image+video
  imageModel: 'nano-banana-pro',// nano-banana-pro, nano-banana-2 (Nano Banana 2.1) or nano-banana-2-lite
  videoModel: 'veo-3.1-fast',   // veo-3.1-fast, veo-3.1-lite, veo-3.1-quality, veo-3.1-lite-low-priority, omni-flash
  aspectRatio: '16:9',          // 16:9, 9:16, 1:1, 4:3 or 3:4 (omni-flash: 16:9 or 9:16)
  firstFrame: true,             // image+video rows: the new image becomes the video's first frame
  upscale: false,               // true = upscale every video to 1080p (free on paid Google AI plans)
  saveToDrive: true,            // false = only write the links (they expire after about 6 hours)
  driveFolderId: '',            // empty = the root of My Drive
  maxRetries: 3,                // tries per step when every account is busy (429) or Google is down (503)
  maxWaitSeconds: 60,           // longest wait before a retry. Longer cooldowns leave the row for the next run
  pollSeconds: 20,              // how often a running video job is checked
  maxVideoMinutes: 15,          // give up on a video job after this long
};
// ---------------------------------------------------------------------------------------------------------
if (!settings.sheetId) throw new Error('Set sheetId in the Settings node: the id of your Google Sheet.');
return [{ json: settings }];

// Rows with a prompt and an empty status, oldest first, at most maxRowsPerRun. Marked "running" before any work,
// so a run that overlaps this one never takes the same row twice. Each row also gets a job_id, and the results are
// written back by that id, so sorting or editing the sheet mid-run can't put them on another row.
const S = $('Settings').first().json;
const blank = v => String(v == null ? '' : v).trim() === '';
const rows = $input.all().map(i => i.json).filter(r => r && r.row_number);
if (rows.length && !('job_id' in rows[0])) throw new Error('Add a job_id column to row 1 of the tab: the workflow fills it and writes the results back by it.');
return rows
  .filter(r => blank(r.status) && !blank(r.prompt))
  .slice(0, S.maxRowsPerRun)
  .map(r => ({ json: { row_number: r.row_number, status: 'running', error: '', job_id: `${$execution.id}-${r.row_number}` } }));

// One state object per picked row: the row's cells checked and filled from Settings. A row that fails a check
// goes straight to the write-back with the reason, and costs nothing.
const S = $('Settings').first().json;
const picked = new Map($('Pick pending rows').all().map(i => [String(i.json.row_number), i.json.job_id]));
const IMAGE_MODELS = ['nano-banana-pro', 'nano-banana-2', 'nano-banana-2-lite'];
const VIDEO_MODELS = ['veo-3.1-fast', 'veo-3.1-lite', 'veo-3.1-quality', 'veo-3.1-lite-low-priority', 'omni-flash'];
const IMAGE_RATIO = { '16:9': '16:9', '9:16': '9:16', '1:1': '1:1', '4:3': '4:3', '3:4': '3:4', landscape: '16:9', portrait: '9:16' };
const VIDEO_RATIO = { '16:9': 'landscape', '9:16': 'portrait', '1:1': '1:1', '4:3': '4:3', '3:4': '3:4', landscape: 'landscape', portrait: 'portrait' };
const cell = v => String(v == null ? '' : v).trim();
const yes = (v, dflt) => { const t = cell(v).toLowerCase(); if (!t) return dflt; return ['yes', 'y', 'true', '1'].includes(t); };
