  const bad = [];
  let type = cell(r.type).toLowerCase().replace(/\s+/g, '') || S.defaultType;
  if (type === 'both' || type === 'video+image') type = 'image+video';
  if (!['image', 'video', 'image+video'].includes(type)) bad.push(`type "${cell(r.type)}" must be image, video or image+video`);
  const imageModel = cell(r.image_model).toLowerCase() || S.imageModel;
  const videoModel = cell(r.video_model).toLowerCase() || S.videoModel;
  const wantsImage = type !== 'video', wantsVideo = type !== 'image';
  if (wantsImage && !IMAGE_MODELS.includes(imageModel)) bad.push(`image_model "${imageModel}" must be one of ${IMAGE_MODELS.join(', ')}`);
  if (wantsVideo && !VIDEO_MODELS.includes(videoModel)) bad.push(`video_model "${videoModel}" must be one of ${VIDEO_MODELS.join(', ')}`);
  const ratio = cell(r.aspect_ratio).toLowerCase() || S.aspectRatio;
  if (!IMAGE_RATIO[ratio]) bad.push(`aspect_ratio "${ratio}" must be 16:9, 9:16, 1:1, 4:3 or 3:4`);
  else if (wantsVideo && videoModel === 'omni-flash' && !['landscape', 'portrait'].includes(VIDEO_RATIO[ratio])) bad.push('omni-flash videos are 16:9 or 9:16 only');
  const up = cell(r.upscale).toLowerCase();
  if (up && !['none', 'no', '1080p', 'yes'].includes(up)) bad.push(`upscale "${cell(r.upscale)}" must be none or 1080p`);
  const email = cell(r.email);
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) bad.push(`email "${email}" is not an email address`);
