    row: r.row_number, jobId: picked.get(String(r.row_number)), prompt: cell(r.prompt), videoPrompt: cell(r.video_prompt), type, imageModel, videoModel,
    imageRatio: IMAGE_RATIO[ratio], videoRatio: VIDEO_RATIO[ratio], email,
    firstFrame: type === 'image+video' && yes(r.use_image_as_first_frame, S.firstFrame),
    upscale: wantsVideo && (up ? ['1080p', 'yes'].includes(up) : !!S.upscale),
    tries: {}, polls: 0, made: false, notes: [],
  };
  if (bad.length) { state.status = 'failed: ' + bad.join('; '); state.route = 'write'; }
  else state.route = wantsImage ? 'image' : 'video';
  return { json: { state } };
});

